// Writes prisma/postgres/schema.prisma from prisma/schema.prisma with the PostgreSQL provider,
// so development (SQLite) and production (PostgreSQL) share one data model.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";

const src = readFileSync("prisma/schema.prisma", "utf8");
const out = src.replace(/provider\s*=\s*"sqlite"/, 'provider = "postgresql"');
if (out === src) throw new Error("Could not find the sqlite provider line in prisma/schema.prisma");
mkdirSync("prisma/postgres", { recursive: true });
writeFileSync(
  "prisma/postgres/schema.prisma",
  "// GENERATED by scripts/make-postgres-schema.mjs — edit prisma/schema.prisma instead.\n" + out,
);
console.log("Wrote prisma/postgres/schema.prisma");
